properties.query:
let svc_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "$" and LogonType == 3 | summarize svc_time=min(TimeGenerated) by TargetUserName, Computer;
let schtask_events = SecurityEvent | where EventID == 4698 | summarize schtask_time=min(TimeGenerated) by SubjectUserName, Computer;
svc_events | join kind=inner schtask_events on $left.TargetUserName == $right.SubjectUserName, Computer | where schtask_time - svc_time between (0min .. 120min)
